// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Fund the contract with 1 ether
        vm.deal(address(c), 1 ether);
        // Non-owner calls sudicideAnyone
        address attacker = address(0x1234);
        vm.deal(attacker, 0);
        vm.prank(attacker);
        bool ok;
        try c.sudicideAnyone() {
            ok = true;
        } catch {
            ok = false;
        }
        // In reference, onlyOwner revert prevents selfdestruct -> contract still alive with balance
        // In bug, selfdestruct succeeds, contract destroyed, balance 0
        assertTrue(!ok);
    }
}
